package agentusage

import (
	"bufio"
	"bytes"
	"errors"
	"io"
)

// readerBufferBytes is the bufio buffer size; longer lines are reassembled.
const readerBufferBytes = 64 << 10

// MaxLineBytes is the longest line (newline excluded) kept in memory.
const MaxLineBytes = 4 << 20

// scanResult describes what scanLines and scanFrom consumed.
type scanResult struct {
	// Consumed is the offset just past the last complete line.
	Consumed int64
	// Oversized counts complete lines longer than maxLen that were skipped.
	Oversized int
	// OversizedAt holds the offset of each skipped line, in order.
	OversizedAt []int64
	// Tail holds the bytes after the last newline (an incomplete line).
	Tail []byte
	// End is base + the number of bytes read (base is 0 for scanLines).
	End int64
	// SkipFrom is the start of an oversized line cut by EOF or a read error, or -1.
	SkipFrom int64
}

// scanFrom is scanLines for a stream positioned at byte base of a file:
// offsets given to fn and returned are absolute. If skipFrom >= 0 the stream
// starts inside an oversized line that began at skipFrom: bytes up to the
// first "\n" are skipped and that line is counted once, at skipFrom.
// Consumed starts at base, End is base plus the bytes read, and SkipFrom is
// the start of an oversized line still unfinished at EOF (-1 otherwise).
func scanFrom(r io.Reader, base, skipFrom int64, maxLen int, fn func(line []byte, off int64)) (scanResult, error) {
	br := bufio.NewReaderSize(r, readerBufferBytes)
	res := scanResult{Consumed: base, End: base, SkipFrom: -1}
	var (
		pending  []byte // line prefix reassembled across buffer fills
		skipping = skipFrom >= 0
		start    = base // offset of the current line's first byte
	)
	if skipping {
		start = skipFrom
	}
	for {
		chunk, err := br.ReadSlice('\n')
		res.End += int64(len(chunk))
		if !skipping {
			// maxLen+1 bytes are kept so a trailing "\r" does not count against maxLen.
			if len(pending)+len(chunk) > maxLen+2 { // +1 more: chunk may end with "\n"
				skipping, pending = true, nil
			} else {
				pending = append(pending, chunk...)
			}
		}
		switch {
		case err == nil:
			if skipping {
				res.skip(start)
			} else {
				res.emit(pending, start, maxLen, fn)
			}
			res.Consumed = res.End
			start, pending, skipping = res.End, pending[:0], false
		case errors.Is(err, bufio.ErrBufferFull):
		case errors.Is(err, io.EOF):
			if skipping {
				res.SkipFrom = start
			} else {
				res.Tail = bytes.Clone(pending)
			}
			return res, nil
		default:
			if skipping {
				res.SkipFrom = start // keep the oversized line resumable
			}
			return res, err
		}
	}
}

// scanLines calls fn for every complete, non-empty line of r no longer
// than maxLen bytes. off is the offset of the line's first byte; line has no
// trailing "\n" or "\r" and is only valid during the call: fn must copy it
// to keep it. Complete lines longer than maxLen are skipped without being held
// in memory. An incomplete final line is returned in Tail whatever its
// length, unless it already exceeds maxLen: it is then dropped, and counted in
// neither Consumed nor Oversized (it may never be completed). A Tail of
// maxLen+1 or maxLen+2 bytes is still kept (the cutoff is maxLen+2, since a
// "\r" may follow); one longer than that is dropped.
func scanLines(r io.Reader, maxLen int, fn func(line []byte, off int64)) (scanResult, error) {
	return scanFrom(r, 0, -1, maxLen, fn)
}

// emit trims the line terminator from raw (which ends with "\n") and hands
// the line to fn, or counts it as oversized.
func (res *scanResult) emit(raw []byte, off int64, maxLen int, fn func([]byte, int64)) {
	line := bytes.TrimSuffix(bytes.TrimSuffix(raw, []byte("\n")), []byte("\r"))
	switch {
	case len(line) > maxLen:
		res.skip(off)
	case len(line) > 0:
		fn(line, off)
	}
}

// skip counts one oversized line starting at off.
func (res *scanResult) skip(off int64) {
	res.Oversized++
	res.OversizedAt = append(res.OversizedAt, off)
}
package agentusage

import (
	"errors"
	"os"
)

// errNotPlain is returned when a path is not what Lstat said it was a moment
// ago (swapped for a link or another file). It is fixed so it never carries
// a path or content.
var errNotPlain = errors.New("agentusage: path changed while being opened")

// errNotRegular is returned when a path is a symbolic link or not a regular
// file as seen by Lstat.
var errNotRegular = errors.New("agentusage: not a regular file")

// openPlain opens path only if it is not a symbolic link and its mode, as
// reported by Lstat, matches wantDir. The opened handle is compared with the
// Lstat result (os.SameFile), which closes the window between checking and
// opening. On Windows the file identity is read lazily, at the SameFile call.
// A missing path yields an error satisfying os.ErrNotExist; a path of the
// wrong kind yields (nil, nil).
//
// Known limit, accepted: a regular file swapped for a FIFO between Lstat and
// Open makes os.Open block until a writer appears, before the SameFile check
// can run. Closing it would need O_NONBLOCK, which the os package does not
// offer portably. The window is tiny and the attacker must already control
// the transcripts directory.
func openPlain(path string, wantDir bool) (*os.File, error) {
	li, err := os.Lstat(path)
	if err != nil {
		return nil, err
	}
	if li.IsDir() != wantDir || (!wantDir && !li.Mode().IsRegular()) {
		return nil, nil
	}
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	fi, err := f.Stat()
	if err != nil || !os.SameFile(li, fi) {
		_ = f.Close()
		if err == nil {
			err = errNotPlain
		}
		return nil, err
	}
	return f, nil
}
package agentusage

import (
	"io"
	"path/filepath"
	"sort"
)

// ParseSession aggregates the usage of every agent of a session. It fails
// only if the parent transcript cannot be opened; a sub-agent that cannot be
// read stays in Agents with no tokens and a FileIssue.
func ParseSession(files SessionFiles) (Usage, error) {
	subs := append([]SubAgentFiles(nil), files.SubAgents...)
	sort.Slice(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
	t := newTable()
	agents := []Agent{{Main: true, State: StateUnknown}}
	var meta Diagnostics // MetaMissing and MetaUnreadable
	var truncated []string
	parentName := sanitizeLabel(filepath.Base(files.Parent))
	tail, err := parseFile(t, "", parentName, parentRank, files.Parent)
	if err != nil {
		return Usage{}, baseOnly(err)
	}
	if tail {
		truncated = append(truncated, parentName)
	}
	for _, sa := range subs {
		ag := agentFromMeta(&meta, sa)
		name := sanitizeLabel(filepath.Base(sa.Transcript))
		rank := transcriptRank(ag.ID, name, sa.ID, sa.Transcript)
		ag.key = rank
		agents = append(agents, ag)
		tail, err := parseFile(t, rank, name, rank, sa.Transcript)
		if err != nil {
			t.addFileIssue(name, pos{rank: rank}, IssueOpenFailed)
		}
		if tail {
			truncated = append(truncated, name)
		}
	}
	agents, diag, versions := t.finish(agents)
	diag.MetaMissing, diag.MetaUnreadable, diag.TruncatedFiles = meta.MetaMissing, meta.MetaUnreadable, truncated
	return Usage{
		SessionID:   sanitizeLabel(files.ID),
		Agents:      agents,
		Versions:    versions,
		Diagnostics: diag,
	}, nil
}

// agentFromMeta builds a sub-agent's identity from its meta file, counting
// a missing or unreadable one in diag.
func agentFromMeta(diag *Diagnostics, sa SubAgentFiles) Agent {
	ag := Agent{ID: sanitizeLabel(sa.ID)}
	if sa.Meta == "" {
		diag.MetaMissing++
		return ag
	}
	m, err := readMeta(sa.Meta)
	if err != nil {
		diag.MetaUnreadable++
		return ag
	}
	ag.Type, ag.State, ag.SpawnDepth = m.AgentType, m.state(), m.SpawnDepth
	return ag
}

// parseFile folds one transcript into the table for agent ("" for the
// parent) and reports whether it ends with an incomplete line. It fails only
// if the file cannot be opened.
func parseFile(t *table, agent, name, rank, path string) (bool, error) {
	f, err := openPlain(path, false)
	if err != nil {
		return false, err
	}
	if f == nil {
		return false, errNotRegular
	}
	defer func() { _ = f.Close() }()
	return parseReader(t, agent, name, rank, f), nil
}

// parseReader folds r into t for agent; name is the file's sanitized base
// name and rank its position rank. It reports whether r ends with an
// incomplete line. A read error mid-stream keeps what was read and is
// recorded as an IssueReadError at the offset consumed; it is not an
// unreadable line.
func parseReader(t *table, agent, name, rank string, r io.Reader) bool {
	res, err := scanLines(r, MaxLineBytes, func(line []byte, off int64) {
		t.addLine(agent, name, pos{rank: rank, off: off}, line)
	})
	for _, off := range res.OversizedAt {
		t.addOversized(name, pos{rank: rank, off: off})
	}
	if err != nil {
		t.addFileIssue(name, pos{rank: rank, off: res.Consumed}, IssueReadError)
	}
	return len(res.Tail) > 0
}
package agentusage

import (
	"encoding/json"
	"errors"
	"io"
)

// State tells whether a sub-agent has finished.
type State int

const (
	StateUnknown State = iota
	StateFinished
	StateUnfinished
)

// meta is the subset of agent-<id>.meta.json that is read. The description
// and worktree path keys are deliberately absent: they are never decoded.
type meta struct {
	AgentType  string
	Finished   *bool
	SpawnDepth int
}

// wireMeta keeps every field raw: one of an unexpected type costs that field
// only. A finished value that is not a boolean yields StateUnknown, not an
// error.
type wireMeta struct {
	AgentType  json.RawMessage `json:"agentType"`
	Finished   json.RawMessage `json:"finished"`
	SpawnDepth json.RawMessage `json:"spawnDepth"`
}

// maxMetaBytes is the largest meta file read; a bigger one is refused.
const maxMetaBytes = 1 << 20

// Fixed messages because encoding/json errors can quote file content.
var (
	errMalformedMeta = errors.New("agentusage: malformed meta file")
	errMetaTooBig    = errors.New("agentusage: meta file too large")
	errMetaNotPlain  = errors.New("agentusage: meta file is not a regular file")
)

// readMeta reads a meta file. A missing file yields an error satisfying
// errors.Is(err, os.ErrNotExist). A symbolic link or non-regular file is
// refused, and reading is bounded by maxMetaBytes.
func readMeta(path string) (meta, error) {
	f, err := openPlain(path, false)
	if err != nil {
		return meta{}, err
	}
	if f == nil {
		return meta{}, errMetaNotPlain
	}
	defer func() { _ = f.Close() }()
	b, err := io.ReadAll(io.LimitReader(f, maxMetaBytes+1))
	if err != nil {
		return meta{}, err
	}
	if len(b) > maxMetaBytes {
		return meta{}, errMetaTooBig
	}
	var w wireMeta
	if json.Unmarshal(b, &w) != nil {
		return meta{}, errMalformedMeta
	}
	m := meta{AgentType: sanitizeLabel(optString(w.AgentType))}
	var fin bool
	if json.Unmarshal(w.Finished, &fin) == nil && string(w.Finished) != "null" {
		m.Finished = &fin // absent, null or a wrong type: stays nil
	}
	if len(w.SpawnDepth) > 0 {
		_ = json.Unmarshal(w.SpawnDepth, &m.SpawnDepth) // wrong type: stays 0
		m.SpawnDepth = max(m.SpawnDepth, 0)
	}
	return m, nil
}

// state maps the finished flag; absent or null is StateUnknown.
func (m meta) state() State {
	switch {
	case m.Finished == nil:
		return StateUnknown
	case *m.Finished:
		return StateFinished
	}
	return StateUnfinished
}
