	// maxVersions of them (the smallest positions).
	versions map[string]pos
}

func newTable() *table {
	return &table{
		entries:  map[msgKey]*entry{},
		spill:    map[string]*spill{},
		capped:   map[string][]issueAt{},
		versions: map[string]pos{},
	}
