			}
			if fr.part != nil && len(fr.part.entries) > 0 {
				t.Errorf("read something from an unusable path: %v", ids(fr.part))
			}
			if fr.next.offset != 0 || fr.next.id != nil {
				t.Errorf("cursor moved: offset=%d id nil=%v", fr.next.offset, fr.next.id == nil)
			}
		})
	}
}

